input.command:
node smoke.ts && node --input-type=module - <<'EOF'
import assert from 'node:assert/strict';
import { screenPayment } from './impl.ts';

const attempt = (overrides = {}) => ({
  id: 'pay-1', customerId: 'customer-1', amountCents: 10_000,
  cardCountry: 'US', ipCountry: 'US', priorPayments: 1, ...overrides,
});

assert.deepEqual(screenPayment(attempt()), { action: 'allow', reasons: [] });
assert.equal(screenPayment(attempt({ cardCountry: 'US', ipCountry: 'CA' })).action, 'block');
assert.equal(screenPayment(attempt({ amountCents: 50_001, priorPayments: 0 })).action, 'review');
assert.equal(screenPayment(attempt({ amountCents: 50_000, priorPayments: 0 })).action, 'allow');
assert.equal(screenPayment(attempt({ amountCents: 50_001, priorPayments: 1 })).action, 'allow');
assert.equal(screenPayment(attempt({ amountCents: 50_001, priorPayments: 0, ipCountry: 'CA' })).action, 'block');
console.log('ticket checks -> 6 passed');
EOF
